#include <vector>
#include <unordered_set>
using namespace std;

class Solution {
public:
    vector<int> fairCandySwap(vector<int>& A, vector<int>& B) {
        int sumA = 0, sumB = 0;
        for (int x : A) sumA += x;
        for (int x : B) sumB += x;
        int diff = (sumA - sumB) / 2;
        unordered_set<int> setB(B.begin(), B.end());

        for (int x : A) {
            if (setB.count(x - diff)) return {x, x - diff};
        }

        return {};
    }
};
